#include <stdio.h>

int main() {
    int years[] = {1900, 2000, 2100, 2400};
    for (int i = 0; i < 4; i++) {
        int y = years[i];
        int leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
        printf("%d %s\n", y, leap ? "leap" : "common");
    }
    return 0;
}
